const GRADIENT_CONSTANT_P3=0.2054731547832489;
const Z9=[0,0,0,0,0,0,0,0,0];

function sharedComp1(sv,tV,c1){var cnt=0;for(var i=0;i<9;i++){if(c1[i]*tV===1)cnt++;}return sv.map(function(){return cnt;});}
function sharedComp2(sv,tV,c2){var mx=0;for(var i=0;i<9;i++){if(c2[i]>mx)mx=c2[i];}var a=1-mx;var o=(a>0.9)?1:0;return{out:sv.map(function(){return o;}),st:o===1?"FREE":"BLOCKED"};}
function sharedComp3Gradient(cY){return cY===1?GRADIENT_CONSTANT_P3:0;}
function sharedComp4Routing(sv,ci,si,cbZ){
    if(sv===1){
        var zBlock=cbZ&&cbZ[ci]?cbZ[ci]:Z9;
        return(zBlock[si]!==undefined)?zBlock[si]:0;
    }
    return 0;
}

let PART=4;
switch(PART){
    case 4:
        return allChannelsSliceValuesAtOutputCell.map(function(s,ci){
            return s.map(function(sv,si){
                return sharedComp4Routing(sv,ci,si,conditionalBlockZ);
            });
        });
    case 3:
        return allChannelsSliceValuesAtOutputCell.map(function(s,ci){
            return s.map(function(v,si){
                var yBlock=conditionalBlockY&&conditionalBlockY[ci]?conditionalBlockY[ci]:Z9;
                return sharedComp3Gradient(yBlock[si]);
            });
        });
    case 2:
        return allChannelsSliceValuesAtOutputCell.map(function(s,ci){
            var rBlock=conditionalBlockR&&conditionalBlockR[ci]?conditionalBlockR[ci]:Z9;
            return sharedComp2(s,allChannelsTargetValuesAtOutputCell[ci],rBlock).out;
        });
    case 1:
        return allChannelsSliceValuesAtOutputCell.map(function(s,ci){
            var xBlock=conditionalBlockX&&conditionalBlockX[ci]?conditionalBlockX[ci]:Z9;
            return sharedComp1(s,allChannelsTargetValuesAtOutputCell[ci],xBlock);
        });
    default:
        return allChannelsSliceValuesAtOutputCell.map(function(s,ci){
            return s.map(function(sv,si){
                return sharedComp4Routing(sv,ci,si,conditionalBlockZ);
            });
        });
}

